"""Reference re-implementation of json-tui's INITIAL view rendering.
Compared byte-exactly against the real executable's frame 0."""
import json, re

ESC = b'\x1b'
def col(code, txt):
    return b'\x1b[%dm\x1b[49m' % code + txt + b'\x1b[39m\x1b[49m'
def bold(txt):
    return b'\x1b[1m' + txt + b'\x1b[22m'
def inv(txt):
    return b'\x1b[7m' + txt + b'\x1b[27m'
def inv_col(code, txt):
    return b'\x1b[7m\x1b[%dm\x1b[49m' % code + txt + b'\x1b[27m\x1b[39m\x1b[49m'

KEY, STR, NUM, BOOL, NUL, DIM = 94, 92, 96, 93, 91, 90

def scalar_bytes(v, selected=False):
    if v is None:
        code, txt = NUL, b'null'
    elif v is True:
        code, txt = BOOL, b'true'
    elif v is False:
        code, txt = BOOL, b'false'
    elif isinstance(v, str):
        code, txt = STR, json.dumps(v).encode()
    else:
        code, txt = NUM, json.dumps(v).encode()
    return inv_col(code, txt) if selected else col(code, txt)

def is_obj(v): return isinstance(v, dict)
def is_arr(v): return isinstance(v, list)
def is_cont(v): return is_obj(v) or is_arr(v)

def table_view(v):
    return is_arr(v) and len(v) >= 2 and all(is_obj(x) for x in v)

def expanded(v, depth):
    """THE INFERRED PREDICATE"""
    if not is_cont(v):
        return False
    if depth == 0:
        return True
    return depth == 1 and is_obj(v)

TV = b'   ' + col(DIM, b'(table view)')

def render(v, depth=0, key=None, last=True, selected_path=(), path=()):
    """returns list of (visible_width, bytes) lines"""
    sel = (path == tuple(selected_path))
    ind = b'  ' * depth
    pre = ind
    prew = len(ind)
    if key is not None:
        kb = json.dumps(key).encode()
        pre = pre + col(KEY, kb) + b': '
        prew += len(kb) + 2
    out = []
    if not is_cont(v):
        body = scalar_bytes(v, sel)
        w = prew + len(json.dumps(v).encode() if not isinstance(v, bool) and v is not None
                       else (b'true' if v is True else b'false' if v is False else b'null'))
        line = pre + body + (b',' if not last else b'')
        out.append((w + (0 if last else 1), line))
        return out
    op, cl = (b'{', b'}') if is_obj(v) else (b'[', b']')
    if not expanded(v, depth):
        txt = op + b'...' + cl + (b',' if not last else b'')
        line = pre + (inv(txt) if sel else bold(txt))
        w = prew + len(txt)
        if table_view(v):
            line += TV
            w += 3 + 12
        out.append((w, line))
        return out
    # expanded
    line = pre + (inv(op) if sel else bold(op))
    w = prew + 1
    if table_view(v):
        line += TV
        w += 3 + 12
    out.append((w, line))
    items = sorted(v.items()) if is_obj(v) else [(None, x) for x in v]
    for i, (k, child) in enumerate(items):
        out += render(child, depth + 1, k, i == len(items) - 1,
                      selected_path, path + (i,))
    closing = ind + cl + (b',' if not last else b'')
    out.append((len(ind) + 1 + (0 if last else 1), closing))
    return out

def frame_body(doc):
    lines = render(doc)
    mx = max(w for w, _ in lines)
    return b'\r\n'.join(b + b' ' * (mx - w) for w, b in lines)

